mapper.select:
SELECT COUNT(*) FROM VW_ACTIVE_PRODUCTS WHERE 1 = 1
AND PR_NAME LIKE CONCAT('%', #{searchKeyword}, '%')
AND PR_CATEGORY = #{pr_category}

SELECT COUNT(*) 
FROM VW_ACTIVE_PRODUCTS_COMMENTS 
WHERE PR_ID = #{pr_id}

SELECT * 
FROM VW_ACTIVE_PRODUCTS_COMMENTS 
WHERE PR_ID = #{pr_id}

SELECT pc.*, o.US_ID FROM VW_ACTIVE_PRODUCTS_COMMENTS pc JOIN PRODUCTS_ORDERS_ITEMS i ON pc.PROR_ITEM_ID = i.PROR_ITEM_ID JOIN PRODUCTS_ORDERS o ON i.PROR_MASTER_ID = o.PROR_MASTER_ID WHERE pc.PR_ID = #{pr_id}
ORDER BY pc.PRC_RATING DESC, pc.PRC_START_DATE DESC
ORDER BY pc.PRC_START_DATE DESC, pc.PRC_NO DESC
AND o.US_ID = #{us_id} ORDER BY pc.PRC_START_DATE DESC, pc.PRC_NO DESC
ORDER BY pc.PRC_NO DESC
LIMIT #{rowFirst}, #{rowSizePerPage}

mapper.update:
UPDATE PRODUCTS_COMMENTS 
SET PRC_STATUS = "N"
WHERE PRC_NO = #{prc_no}

mapper.delete:
UPDATE PRODUCTS_QNA 
SET PRQ_STATUS = "N"
WHERE PRQ_NO = #{prq_no}

mapper.select:
SELECT * FROM PRODUCTS_SHOPPING_CARTS 
WHERE US_ID = #{us_id}
ORDER BY PRSC_NO ASC

mapper.update:
UPDATE PRODUCTS_SHOPPING_CARTS 
SET PRSC_QUANTITY = #{prsc_quantity},
    PRSC_PRICE = #{prsc_price}
WHERE PRSC_NO = #{prsc_no}

mapper.delete:
